/* ------------------------------------------------------------------ */
/* Hand-added: A6XX PM4 packet-header encoding.                         */
/*                                                                      */
/* Provenance: Linux drivers/gpu/drm/msm/adreno/adreno_gpu.h            */
/* (PM4_PARITY, PKT4, OUT_PKT7) and adreno_pm4.xml (CP_TYPE4_PKT /      */
/* CP_TYPE7_PKT).  A6XX uses type-4 packets to write registers and      */
/* type-7 packets for opcodes; BOTH carry a parity bit computed over    */
/* the count/register/opcode nibbles.  The older a3xx-style header      */
/*   (7u<<28) | (cnt & 0x3fff) | ((opcode & 0xff) << 8)                 */
/* is WRONG for a6xx (no parity, wrong opcode field position) and must  */
/* not be used - the CP rejects it.  These macros are named ADRENO_PKT4 */
/* / ADRENO_PKT7 to avoid colliding with the PKT4 opcode constant       */
/* (0x04) defined above.                                                */
/* ------------------------------------------------------------------ */
#define CP_TYPE4_PKT                                           0x40000000u
#define CP_TYPE7_PKT                                           0x70000000u

/* Maximum number of register values in one type-4 packet (adreno_gpu.h). */
#define TYPE4_MAX_PAYLOAD                                      127u

/* PM4 header parity bit (adreno_gpu.h PM4_PARITY, verbatim). */
#define PM4_PARITY(val) \
	((0x9669u >> (0xFu & ((val) ^ ((val) >> 4) ^ ((val) >> 8) ^ \
	  ((val) >> 12) ^ ((val) >> 16) ^ ((val) >> 20) ^ ((val) >> 24) ^ \
	  ((val) >> 28)))) & 1u)

/* Type-4: write `_cnt` consecutive registers starting at register index
   `_reg` (adreno_gpu.h PKT4).  The payload dwords follow the header. */
#define ADRENO_PKT4(_reg, _cnt) \
	(CP_TYPE4_PKT | (((_cnt) & 0x7fu) << 0) | (PM4_PARITY(_cnt) << 7) | \
	 (((_reg) & 0x3ffffu) << 8) | (PM4_PARITY(_reg) << 27))

/* Type-7: opcode `_opcode` with `_cnt` payload dwords (adreno_gpu.h
   OUT_PKT7). */
#define ADRENO_PKT7(_opcode, _cnt) \
	(CP_TYPE7_PKT | (((_cnt) & 0x3fffu) << 0) | (PM4_PARITY(_cnt) << 15) | \
	 (((_opcode) & 0x7fu) << 16) | (PM4_PARITY(_opcode) << 23))

#endif /* ADRENO_PM4_H */
